package com.noop.analytics.calorie

import com.noop.analytics.UserProfile
import com.noop.data.GravitySample
import com.noop.data.HrSample
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The measured-basal model against an independent implementation of the same description.
 *
 * `Tools/dynamic_hrr_oracle.py` is a second, standalone implementation written from the same
 * notebook sections this model came from. It is run over the two days built below and its output is
 * pasted here verbatim, so a port that drifts fails rather than agreeing with itself. Regenerate the
 * literals with `python3 Tools/dynamic_hrr_oracle.py` and paste the lines it prints.
 *
 * Day A is a whole day worn over two sessions, morning and midday, so the diurnal fuel curve is read
 * at every hour and the silence between the sessions splits them. Day B is a second wearer with
 * every input day A leaves at its default moved: a different sex, a measured maximal oxygen uptake
 * in place of the estimate, the wearer's own heart-rate zone starts, and every setting off its
 * shipped value.
 *
 * Day A's four per-minute series are pinned one minute in sixty; its day figures already integrate
 * every second, and the whole series is a hundred thousand digits nobody would read. Day B is short
 * enough to pin minute by minute.
 */
class DynamicHrrOracleTest {

    private fun day(
        spanS: Int,
        worn: List<IntRange>,
        bpmAt: (Int) -> Int,
        motionAt: (Int) -> Double,
        hasBeat: (Int) -> Boolean,
        profile: UserProfile,
        vitals: CalorieVitals,
    ): CalorieTimeline {
        val seconds = worn.flatten()
        return DynamicHrrModel(profile, vitals).timeline(
            0L, spanS.toLong(),
            CalorieInputs(
                hr = seconds.map { HrSample("d", it.toLong(), bpmAt(it)) },
                gravity = seconds.map {
                    GravitySample("d", it.toLong(), x = 0.0, y = 0.0, z = 1.0, dynAccel = motionAt(it))
                },
                rr = seconds.filter(hasBeat).map { it.toLong() to 1 },
            ),
        )
    }

    private fun assertSeries(recorded: String, produced: List<Double?>, everyNth: Int) {
        val expected = recorded.trim().replace("\n", "").replace(" ", "").split(",")
        val sampled = produced.filterIndexed { i, _ -> i % everyNth == 0 }
        assertEquals(expected.size, sampled.size)
        for (i in expected.indices) {
            if (expected[i] == "null") {
                assertEquals("minute ${i * everyNth}", null, sampled[i])
            } else {
                assertEquals("minute ${i * everyNth}", expected[i].toDouble(), sampled[i]!!, 1e-12)
            }
        }
    }

    // ── Day A: a whole day, two wear sessions, everything at its default ──────────────────────

    private fun quietA(i: Int): Boolean =
        i < 1_800 || i in 3_600 until 5_400 || i in 30_600 until 34_200 || i in 37_800 until 41_400

    private fun bpmA(i: Int): Int = when {
        i < 1_800 -> 52
        i < 3_600 -> 100 + (i % 37)
        i < 5_400 -> 56
        i < 7_200 -> 130 - (i % 23)
        i < 34_200 -> 54
        i < 37_800 -> 110 + (i % 31)
        else -> 58
    }

    private val dayA: CalorieTimeline = day(
        spanS = 86_400,
        worn = listOf(0 until 7_200, 30_600 until 41_400),
        bpmAt = ::bpmA,
        motionAt = { if (quietA(it)) 0.005 else 0.4 },
        hasBeat = { it % 3 != 0 },
        profile = UserProfile(weightKg = 80.0, heightCm = 180.0, age = 35.0, sex = "male"),
        vitals = CalorieVitals(hrmax = 180.0, restingHR = 50.0),
    )

    @Test
    fun aWholeDay_matchesTheReferenceImplementationsDayFigures() {
        assertEquals(2990.265489593724, dayA.dayTotalKcal, 1e-9)
        assertEquals(1165.0184895936784, dayA.dayActiveKcal, 1e-9)
        assertEquals(
            4.0,
            dayA.extras.getValue(DynamicHrrModel.Extra.QUIET_WINDOW_COUNT),
            0.0,
        )
        assertEquals(
            58.0,
            dayA.extras.getValue(CalorieTimeline.MEASURED_BASAL_HR_BPM),
            0.0,
        )
        assertEquals(
            162.4212868258106,
            dayA.extras.getValue(DynamicHrrModel.Extra.FAT_GRAMS),
            1e-9,
        )
        assertEquals(
            356.9525349831962,
            dayA.extras.getValue(DynamicHrrModel.Extra.CHO_GRAMS),
            1e-9,
        )
        assertEquals(
            1.0,
            dayA.extras.getValue(DynamicHrrModel.Extra.HR_COVERAGE_FRAC),
            0.0,
        )
    }

    @Test
    fun aWholeDay_matchesTheReferenceImplementationsMinuteSeries() {
        assertSeries(A_MINUTE_ACTIVE_KCAL, dayA.activeKcal.toList(), everyNth = 60)
        assertSeries(
            A_MINUTE_DELTA_HR_BPM,
            dayA.labeledSeries.getValue(DynamicHrrModel.Label.DELTA_HR),
            everyNth = 60,
        )
        assertSeries(
            A_MINUTE_BASAL_HR_BPM,
            dayA.labeledSeries.getValue(DynamicHrrModel.Label.BASAL_HR),
            everyNth = 60,
        )
        assertSeries(
            A_MINUTE_FAT_PERCENTAGE,
            dayA.labeledSeries.getValue(DynamicHrrModel.Label.FAT_PERCENTAGE),
            everyNth = 60,
        )
    }

    // ── Day B: a second wearer, with every default moved ──────────────────────────────────────

    private fun quietB(i: Int): Boolean = i < 2_400 || i >= 6_000

    private fun bpmB(i: Int): Int = when {
        i < 2_400 -> 64
        i < 6_000 -> 96 + (i % 19)
        else -> 68
    }

    private val dayB: CalorieTimeline = day(
        spanS = 10_800,
        worn = listOf(0 until 10_800),
        bpmAt = ::bpmB,
        motionAt = { if (quietB(it)) 0.02 else 0.5 },
        hasBeat = { it % 2 == 0 },
        profile = UserProfile(
            weightKg = 58.0, heightCm = 164.0, age = 48.0, sex = "female",
            vo2maxOverride = 41.0,
            hrZoneThresholds = listOf(88.0, 110.0, 132.0, 154.0, 166.0),
            dynamicHrrModelSetting = DynamicHrrModelSetting(
                sessionGapS = 600,
                minHrCoverageFrac = 0.4,
                hampelRadiusS = 3,
                hampelSigmas = 2.0,
                suppressPeaks = false,
                motionStillG = 0.03,
                motionSmoothS = 6,
                basalMinWindowS = 240,
                basalHrRangeBpm = 6.0,
                basalStillFrac = 0.9,
                basalBeatCoverageFrac = 0.3,
                restSmoothS = 20,
                restSmoothMinSamples = 15,
                basalHrSeedOffsetBpm = 3.0,
                reserveRampBandBpm = 7.0,
                measuredBasalKcalDay = 1_400.0,
                basalFatNight = 0.7,
                basalFatDay = 0.25,
                basalFatDayStartHour = 8.0,
                basalFatDayEndHour = 18.0,
                activeFatAtZone1 = 0.9,
                activeFatAtZone2Top = 0.5,
            ),
        ),
        vitals = CalorieVitals(hrmax = 172.0, restingHR = 62.0),
    )

    @Test
    fun aSecondWearer_matchesTheReferenceImplementationsDayFigures() {
        assertEquals(375.30013565407796, dayB.dayTotalKcal, 1e-9)
        assertEquals(200.30013565407816, dayB.dayActiveKcal, 1e-9)
        assertEquals(
            2.0,
            dayB.extras.getValue(DynamicHrrModel.Extra.QUIET_WINDOW_COUNT),
            0.0,
        )
        assertEquals(
            68.0,
            dayB.extras.getValue(CalorieTimeline.MEASURED_BASAL_HR_BPM),
            0.0,
        )
        assertEquals(
            25.567268131842905,
            dayB.extras.getValue(DynamicHrrModel.Extra.FAT_GRAMS),
            1e-9,
        )
        assertEquals(
            32.918979320671866,
            dayB.extras.getValue(DynamicHrrModel.Extra.CHO_GRAMS),
            1e-9,
        )
        assertEquals(
            1.0,
            dayB.extras.getValue(DynamicHrrModel.Extra.HR_COVERAGE_FRAC),
            0.0,
        )
    }

    @Test
    fun aSecondWearer_matchesTheReferenceImplementationsMinuteSeries() {
        assertSeries(B_MINUTE_ACTIVE_KCAL, dayB.activeKcal.toList(), everyNth = 1)
        assertSeries(
            B_MINUTE_DELTA_HR_BPM,
            dayB.labeledSeries.getValue(DynamicHrrModel.Label.DELTA_HR),
            everyNth = 1,
        )
        assertSeries(
            B_MINUTE_BASAL_HR_BPM,
            dayB.labeledSeries.getValue(DynamicHrrModel.Label.BASAL_HR),
            everyNth = 1,
        )
        assertSeries(
            B_MINUTE_FAT_PERCENTAGE,
            dayB.labeledSeries.getValue(DynamicHrrModel.Label.FAT_PERCENTAGE),
            everyNth = 1,
        )
    }

